<?php
if(!defined('ABSPATH'))exit;
function legacyx_reports_menu(){add_submenu_page('legacyx-firm-os','Reports & Analytics','Reports','legacyx_view_reports','legacyx-reports','legacyx_render_reports_dashboard');}add_action('admin_menu','legacyx_reports_menu',20);
function legacyx_reports_count($type){$q=wp_count_posts($type);$n=0;foreach(array('publish','private','draft','pending') as $s)if($q&&isset($q->$s))$n+=(int)$q->$s;return $n;}
function legacyx_reports_meta_count($type,$key,$values){$q=new WP_Query(array('post_type'=>$type,'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_query'=>array(array('key'=>$key,'value'=>(array)$values,'compare'=>'IN'))));return (int)$q->found_posts;}
function legacyx_reports_money($v){return function_exists('legacyx_money')?legacyx_money($v):'$'.number_format((float)$v,2);}
function legacyx_reports_monthly_activity($months=6){$out=array();for($i=$months-1;$i>=0;$i--){$ts=strtotime('-'.$i.' months',current_time('timestamp'));$year=(int)date('Y',$ts);$month=(int)date('n',$ts);$label=date('M Y',$ts);$q=new WP_Query(array('post_type'=>array('legacyx_client','legacyx_assessment','legacyx_application','legacyx_work_item','legacyx_invoice','legacyx_engagement','legacyx_appointment','legacyx_message'),'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','date_query'=>array(array('year'=>$year,'monthnum'=>$month,'column'=>'post_date'))));$out[$label]=(int)$q->found_posts;}return $out;}
function legacyx_render_reports_dashboard(){if(!current_user_can('legacyx_view_reports'))wp_die('You do not have access to Legacy X Firm reports.','Legacy X Firm',array('response'=>403));
 $clients=legacyx_reports_count('legacyx_client');$assess=legacyx_reports_count('legacyx_assessment');$apps=legacyx_reports_count('legacyx_application');$active_apps=legacyx_reports_meta_count('legacyx_application','_legacyx_status',array('Draft','Preparing','Ready','Submitted','Under Review','Additional Information Requested'));$approved_apps=legacyx_reports_meta_count('legacyx_application','_legacyx_status',array('Approved','Funded'));$work=legacyx_reports_count('legacyx_work_item');$open_work=legacyx_reports_meta_count('legacyx_work_item','_legacyx_work_status',array('Open','In Progress','Waiting on Client','Submitted','Under Review'));$eng=legacyx_reports_count('legacyx_engagement');$active_eng=legacyx_reports_meta_count('legacyx_engagement','_legacyx_status',array('Active','In Progress','Onboarding'));$appt=legacyx_reports_count('legacyx_appointment');$messages=legacyx_reports_count('legacyx_message');$invoices=legacyx_reports_count('legacyx_invoice');$open_invoices=legacyx_reports_meta_count('legacyx_invoice','_legacyx_status',array('Open','Partially Paid','Past Due'));
 $balance=0;$paid=0;$invoice_posts=get_posts(array('post_type'=>'legacyx_invoice','post_status'=>'any','numberposts'=>-1,'fields'=>'ids'));foreach($invoice_posts as $iid){$amount=(float)get_post_meta($iid,'_legacyx_amount',true);$paid_amt=(float)get_post_meta($iid,'_legacyx_paid_amount',true);$paid+=$paid_amt;$balance+=max(0,$amount-$paid_amt);} $activity=legacyx_reports_monthly_activity(6);$max=max(array_merge(array(1),array_values($activity)));?>
<div class="wrap legacyx-reports"><div class="legacyx-reports-hero"><span>LEGACY X INTELLIGENCE · PHASE 15</span><h1>Reports & Analytics</h1><p>Executive operating intelligence across client relationships, delivery, applications, workflow, communications and billing.</p></div><div class="legacyx-report-metrics"><article><span>Clients</span><strong><?php echo esc_html($clients);?></strong><small><?php echo esc_html($assess);?> assessments</small></article><article><span>Applications</span><strong><?php echo esc_html($active_apps);?></strong><small><?php echo esc_html($approved_apps);?> approved / funded · <?php echo esc_html($apps);?> total</small></article><article><span>Workflow</span><strong><?php echo esc_html($open_work);?></strong><small><?php echo esc_html($work);?> total items</small></article><article><span>Services</span><strong><?php echo esc_html($active_eng);?></strong><small><?php echo esc_html($eng);?> total engagements</small></article><article><span>Open Billing</span><strong><?php echo esc_html($open_invoices);?></strong><small><?php echo esc_html($invoices);?> records</small></article><article><span>Outstanding</span><strong><?php echo esc_html(legacyx_reports_money($balance));?></strong><small><?php echo esc_html(legacyx_reports_money($paid));?> recorded paid</small></article></div>
<div class="legacyx-report-grid"><section><div class="legacyx-report-head"><span>ACTIVITY</span><h2>Six-Month Operating Activity</h2></div><div class="legacyx-bars"><?php foreach($activity as $label=>$count):$pct=$max?max(4,round(($count/$max)*100)):4;?><div class="legacyx-bar-row"><span><?php echo esc_html($label);?></span><div><i style="width:<?php echo esc_attr($pct);?>%"></i></div><strong><?php echo esc_html($count);?></strong></div><?php endforeach;?></div></section><aside><div class="legacyx-report-head"><span>RELATIONSHIP SIGNALS</span><h2>Firm Activity</h2></div><dl><div><dt>Appointments</dt><dd><?php echo esc_html($appt);?></dd></div><div><dt>Messages</dt><dd><?php echo esc_html($messages);?></dd></div><div><dt>Applications requiring action</dt><dd><?php echo esc_html($active_apps);?></dd></div><div><dt>Open workflow items</dt><dd><?php echo esc_html($open_work);?></dd></div></dl></aside></div>
<div class="legacyx-report-note"><strong>Executive reporting foundation</strong><p>This dashboard reports only data already stored inside Legacy X Firm OS. It does not represent audited financial statements, investment performance, guaranteed funding outcomes, or external bureau/lender data.</p></div></div><?php }
function legacyx_reports_styles($hook){if($hook!=='firm-os_page_legacyx-reports')return;wp_register_style('legacyx-reports',false);wp_enqueue_style('legacyx-reports');$css='.legacyx-reports{max-width:1400px;margin:24px 24px 60px 4px;color:#171512}.legacyx-reports-hero{background:#171512;color:#fff;padding:36px 40px;border-radius:4px}.legacyx-reports-hero>span,.legacyx-report-head>span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.legacyx-reports-hero h1{font:40px Georgia,serif;margin:8px 0}.legacyx-reports-hero p{color:#c9c3ba;max-width:780px}.legacyx-report-metrics{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border:1px solid #ded8ce;margin-top:18px}.legacyx-report-metrics article{padding:24px;border-right:1px solid #ded8ce;border-bottom:1px solid #ded8ce}.legacyx-report-metrics span,.legacyx-report-metrics small{display:block;color:#746e65}.legacyx-report-metrics strong{display:block;font:30px Georgia,serif;margin:7px 0}.legacyx-report-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}.legacyx-report-grid section,.legacyx-report-grid aside,.legacyx-report-note{background:#fff;border:1px solid #ded8ce;padding:30px}.legacyx-report-head h2{font:28px Georgia,serif;margin:6px 0 24px}.legacyx-bar-row{display:grid;grid-template-columns:80px 1fr 40px;gap:12px;align-items:center;margin:15px 0}.legacyx-bar-row>div{height:10px;background:#eee9e1}.legacyx-bar-row i{display:block;height:100%;background:#f05a16}.legacyx-bar-row strong{text-align:right}.legacyx-report-grid dl{margin:0}.legacyx-report-grid dl div{display:flex;justify-content:space-between;border-bottom:1px solid #e4dfd6;padding:15px 0}.legacyx-report-grid dt{color:#625d55}.legacyx-report-grid dd{font-weight:800}.legacyx-report-note{margin-top:18px}.legacyx-report-note strong{font:22px Georgia,serif}.legacyx-report-note p{color:#69645d;max-width:900px}@media(max-width:900px){.legacyx-report-metrics{grid-template-columns:repeat(2,1fr)}.legacyx-report-grid{grid-template-columns:1fr}}@media(max-width:600px){.legacyx-report-metrics{grid-template-columns:1fr}.legacyx-reports-hero{padding:28px 24px}.legacyx-reports-hero h1{font-size:34px}}';wp_add_inline_style('legacyx-reports',$css);}add_action('admin_enqueue_scripts','legacyx_reports_styles');
